tree = {'op': '+', 'left': 4, 'right': {'op': '*', 'left': 2, 'right': 5}}
def evaluate(node):
    if isinstance(node, int): return node
    if node['op'] == '+': return evaluate(node['left']) + evaluate(node['right'])
    if node['op'] == '*': return evaluate(node['left']) * evaluate(node['right'])
print("AST Result:", evaluate(tree))

